import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64
.visible .entry bn2d_onepass(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 running_mean_ptr,
    .param .u64 running_var_ptr,
    .param .u64 nb_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .f32 eps,
    .param .f32 momentum,
    .param .u32 training,
    .param .u32 track_stats
)
{
    .reg .pred  %p<32>;
    .reg .b32   %r<80>;
    .reg .b64   %rd<140>;
    .reg .f32   %f<140>;
    // Shared memory for per-block reduction and scalars
    .shared .align 4 .f32 sh_sum[256];
    .shared .align 4 .f32 sh_sumsq[256];
    .shared .align 4 .f32 sh_used_mean;
    .shared .align 4 .f32 sh_used_invstd;
    .shared .align 4 .f32 sh_gamma;
    .shared .align 4 .f32 sh_beta;
    // Load params
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [weight_ptr];
    ld.param.u64 %rd4, [bias_ptr];
    ld.param.u64 %rd5, [running_mean_ptr];
    ld.param.u64 %rd6, [running_var_ptr];
    ld.param.u64 %rd7, [nb_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [C];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [W];
    ld.param.f32 %f1,  [eps];
    ld.param.f32 %f2,  [momentum];
    ld.param.u32 %r5,  [training];
    ld.param.u32 %r6,  [track_stats];
    // Thread/block indices
    mov.u32 %r10, %tid.x;      // tid
    mov.u32 %r11, %ctaid.x;    // block/channel index c
    mov.u32 %r12, %ntid.x;     // blockDim.x
    // Bounds check on channel index
    setp.ge.u32 %p0, %r11, %r2;
    @%p0 bra DONE;
    // Compute sizes
    mul.lo.u32 %r13, %r3, %r4;      // HW
    mul.lo.u32 %r14, %r2, %r13;     // CHW
    mul.lo.u32 %r15, %r1, %r13;     // M = N*HW
    // Precompute base index within channel: base_c = c*HW
    mul.lo.u32 %r16, %r11, %r13;    // base_c
    // Initialize accumulators
    mov.f32 %f10, 0f00000000; // sum
    mov.f32 %f11, 0f00000000; // sumsq
    // Precompute constants
    cvt.u64.u32 %rd93, %r14;        // rdCHW
    cvt.u64.u32 %rd21, %r16;        // base_c (u64)
    // Hoisted: CHW in bytes (stride between batches)
    shl.b64 %rd94, %rd93, 2;          // rdCHW_bytes
    // Prepare vectorized traversal over spatial dimension (t in HW, 4-wide)
    and.b32 %r50, %r13, 0xfffffffc;   // HW4 = HW & ~3
    shl.b32 %r51, %r10, 2;            // t4 = tid * 4
    shl.b32 %r52, %r12, 2;            // stride4 = blockDim.x * 4
    and.b32 %r70, %r16, 3;            // alignment check for base_c
    setp.eq.u32 %p16, %r70, 0;        // base_c % 4 == 0 ?
    // If not aligned for v4, go to scalar accumulation for full range
    @!%p16 bra ACCUM_SCALAR_START;
    // Vectorized accumulation over t in [0, HW4)
LOOP_ACCUM_V:
    setp.ge.u32 %p1, %r51, %r50;
    @%p1 bra LOOP_ACCUM_V_END;
    cvt.u64.u32 %rd22, %r51;          // t4 (u64)
    add.s64 %rd23, %rd21, %rd22;      // off0 (elements)
    // Inner loop over batches N
     mov.u32 %r18, 0;                  // n = 0
     mov.s64 %rd24, %rd23;             // rd_elem = off0
     // Initialize x pointer
     shl.b64 %rd25, %rd24, 2;
     add.s64 %rd26, %rd1, %rd25;       // x_ptr_cur
LOOP_N_ACCUM_V:
     setp.ge.u32 %p13, %r18, %r1;
     @%p13 bra AFTER_N_ACCUM_V;
     // load 4 contiguous elements
       ld.global.ca.v4.f32 {%f12, %f13, %f14, %f15}, [%rd26];
     // accumulate sumsq
     fma.rn.f32 %f11, %f12, %f12, %f11;
     fma.rn.f32 %f11, %f13, %f13, %f11;
     fma.rn.f32 %f11, %f14, %f14, %f11;
     fma.rn.f32 %f11, %f15, %f15, %f11;
     // accumulate sum
     add.f32 %f10, %f10, %f12;
     add.f32 %f10, %f10, %f13;
     add.f32 %f10, %f10, %f14;
     add.f32 %f10, %f10, %f15;
     // advance to next batch element
     add.u32 %r18, %r18, 1;
     add.s64 %rd26, %rd26, %rd94;    // advance x pointer by CHW bytes
     bra LOOP_N_ACCUM_V;
AFTER_N_ACCUM_V:
    // Next spatial t4
    add.u32 %r51, %r51, %r52;
    bra LOOP_ACCUM_V;
LOOP_ACCUM_V_END:
    // Tail scalar accumulation for remaining t in [HW4, HW)
    mov.u32 %r53, %r10;               // t = tid
    add.u32 %r53, %r53, %r50;         // start at HW4 + tid
LOOP_ACCUM_TAIL:
    setp.ge.u32 %p17, %r53, %r13;
    @%p17 bra LOOP_ACCUM_END;
    // off0 = base_c + t
    cvt.u64.u32 %rd22, %r53;
    add.s64 %rd23, %rd21, %rd22;
    // Inner loop over batches N (scalar)
     mov.u32 %r18, 0;
     mov.s64 %rd24, %rd23;
     // Initialize x pointer
     shl.b64 %rd25, %rd24, 2;
     add.s64 %rd26, %rd1, %rd25;       // x_ptr_cur
LOOP_N_ACCUM_TAIL_SC:
     setp.ge.u32 %p18, %r18, %r1;
     @%p18 bra AFTER_N_ACCUM_TAIL_SC;
       ld.global.ca.f32 %f12, [%rd26];
     fma.rn.f32 %f11, %f12, %f12, %f11;
     add.f32 %f10, %f10, %f12;
     add.u32 %r18, %r18, 1;
     add.s64 %rd26, %rd26, %rd94;
     bra LOOP_N_ACCUM_TAIL_SC;
AFTER_N_ACCUM_TAIL_SC:
    add.u32 %r53, %r53, %r12;
    bra LOOP_ACCUM_TAIL;
    // Fallback: full scalar accumulation if misaligned for v4
ACCUM_SCALAR_START:
    mov.u32 %r17, %r10;             // t = tid
LOOP_ACCUM_SCALAR:
    setp.ge.u32 %p19, %r17, %r13;
    @%p19 bra LOOP_ACCUM_END;
    // off0 = base_c + t
    cvt.u64.u32 %rd22, %r17;        // t (u64)
    add.s64 %rd23, %rd21, %rd22;    // off0 (elements)
    // Inner loop over batches N
     mov.u32 %r18, 0;                // n = 0
     mov.s64 %rd24, %rd23;           // rd_elem = off0
     // Initialize x pointer
     shl.b64 %rd25, %rd24, 2;        // *4 bytes
     add.s64 %rd26, %rd1, %rd25;     // addr = x_ptr + rd_elem*4
LOOP_N_ACCUM_SCALAR_INNER:
     setp.ge.u32 %p20, %r18, %r1;
     @%p20 bra AFTER_N_ACCUM_SCALAR_INNER;
       ld.global.ca.f32 %f12, [%rd26];
     fma.rn.f32 %f11, %f12, %f12, %f11;
     add.f32 %f10, %f10, %f12;
     // advance to next batch element
     add.u32 %r18, %r18, 1;
     add.s64 %rd26, %rd26, %rd94;    // rd_elem += CHW bytes
     bra LOOP_N_ACCUM_SCALAR_INNER;
AFTER_N_ACCUM_SCALAR_INNER:
    // Next spatial t
    add.u32 %r17, %r17, %r12;
    bra LOOP_ACCUM_SCALAR;
LOOP_ACCUM_END:
    // Warp-level reduction using shuffles
    // Compute lane and warp id
    mov.u32 %r40, %laneid;         // lane
    shr.u32 %r41, %r10, 5;         // warp_id = tid >> 5
    // Intra-warp reduce sum (f10) and sumsq (f11)
    shfl.sync.down.b32 %f80, %f10, 16, 0x1f, 0xffffffff;
    add.f32 %f10, %f10, %f80;
    shfl.sync.down.b32 %f81, %f11, 16, 0x1f, 0xffffffff;
    add.f32 %f11, %f11, %f81;
    shfl.sync.down.b32 %f80, %f10, 8, 0x1f, 0xffffffff;
    add.f32 %f10, %f10, %f80;
    shfl.sync.down.b32 %f81, %f11, 8, 0x1f, 0xffffffff;
    add.f32 %f11, %f11, %f81;
    shfl.sync.down.b32 %f80, %f10, 4, 0x1f, 0xffffffff;
    add.f32 %f10, %f10, %f80;
    shfl.sync.down.b32 %f81, %f11, 4, 0x1f, 0xffffffff;
    add.f32 %f11, %f11, %f81;
    shfl.sync.down.b32 %f80, %f10, 2, 0x1f, 0xffffffff;
    add.f32 %f10, %f10, %f80;
    shfl.sync.down.b32 %f81, %f11, 2, 0x1f, 0xffffffff;
    add.f32 %f11, %f11, %f81;
    shfl.sync.down.b32 %f80, %f10, 1, 0x1f, 0xffffffff;
    add.f32 %f10, %f10, %f80;
    shfl.sync.down.b32 %f81, %f11, 1, 0x1f, 0xffffffff;
    add.f32 %f11, %f11, %f81;
    // Store per-warp results to shared memory (lane 0 only)
    setp.eq.u32 %p2, %r40, 0;
    @!%p2 bra SKIP_WARP_STORE;
    mov.u64 %rd70, sh_sum;
    mul.wide.u32 %rd71, %r41, 4;
    add.s64 %rd72, %rd70, %rd71;
    st.shared.f32 [%rd72], %f10;
    mov.u64 %rd73, sh_sumsq;
    add.s64 %rd74, %rd73, %rd71;
    st.shared.f32 [%rd74], %f11;
SKIP_WARP_STORE:
    bar.sync 0;
    // Thread 0 reduces across warps and writes totals to shmem[0]
    setp.eq.u32 %p3, %r10, 0;
    @!%p3 bra REDUCE_DONE;
    shr.u32 %r42, %r12, 5;        // num_warps = blockDim.x / 32
    mov.u32 %r43, 0;              // i = 0
    mov.f32 %f20, 0f00000000;     // total sum
    mov.f32 %f22, 0f00000000;     // total sumsq
REDUCE_WARP_LOOP:
    setp.ge.u32 %p14, %r43, %r42;
    @%p14 bra REDUCE_WARP_END;
    mov.u64 %rd75, sh_sum;
    mul.wide.u32 %rd76, %r43, 4;
    add.s64 %rd77, %rd75, %rd76;
    ld.shared.f32 %f21, [%rd77];
    add.f32 %f20, %f20, %f21;
    mov.u64 %rd80, sh_sumsq;
    add.s64 %rd82, %rd80, %rd76;
    ld.shared.f32 %f23, [%rd82];
    add.f32 %f22, %f22, %f23;
    add.u32 %r43, %r43, 1;
    bra REDUCE_WARP_LOOP;
REDUCE_WARP_END:
    mov.u64 %rd85, sh_sum;
    st.shared.f32 [%rd85], %f20;
    mov.u64 %rd86, sh_sumsq;
    st.shared.f32 [%rd86], %f22;
REDUCE_DONE:
    // Thread 0 computes mean/var, selects stats, updates running stats, sets broadcast scalars
    setp.eq.u32 %p4, %r10, 0;
    @!%p4 bra POST_SETUP;
    // Load total sum and sumsq from shmem index 0
    mov.u64 %rd85, sh_sum;
    ld.shared.f32 %f30, [%rd85]; // total sum
    mov.u64 %rd86, sh_sumsq;
    ld.shared.f32 %f31, [%rd86]; // total sumsq
    // mean = sum / M; var = sumsq / M - mean*mean
    cvt.rn.f32.u32 %f32, %r15;          // float(M)
    div.rn.f32 %f33, %f30, %f32;        // mean
    div.rn.f32 %f34, %f31, %f32;        // E[x^2]
    mul.f32 %f35, %f33, %f33;           // mean^2
    sub.f32 %f36, %f34, %f35;           // var
    // Load running stats, gamma, beta for channel c
    mul.wide.u32 %rd87, %r11, 4;
    // weight[c]
    add.s64 %rd30, %rd3, %rd87;
     ld.global.ca.f32 %f40, [%rd30];
    // bias[c]
    add.s64 %rd31, %rd4, %rd87;
     ld.global.ca.f32 %f41, [%rd31];
    // running mean/var
    add.s64 %rd32, %rd5, %rd87;
    add.s64 %rd33, %rd6, %rd87;
     ld.global.ca.f32 %f42, [%rd32]; // running_mean[c]
     ld.global.ca.f32 %f43, [%rd33]; // running_var[c]
    // Determine which stats to use
    // pTraining = training != 0
    setp.ne.u32 %p5, %r5, 0;
    // pTrack = track_stats != 0
    setp.ne.u32 %p6, %r6, 0;
    // pNotTraining = !p5
    not.pred %p7, %p5;
    // pUseRunning = (!training) & track_stats
    and.pred %p8, %p7, %p6;
    // used_mean = pUseRunning ? running_mean : batch_mean
    selp.f32 %f44, %f42, %f33, %p8;
    // used_var = pUseRunning ? running_var : batch_var
    selp.f32 %f45, %f43, %f36, %p8;
    // invstd = 1.0 / sqrt(used_var + eps)
    add.f32 %f46, %f45, %f1;
    sqrt.rn.f32 %f47, %f46;
    // 1.0f
    mov.b32 %f48, 0x3f800000;
    div.rn.f32 %f49, %f48, %f47; // invstd
    // If (training && track_stats) update running stats
    and.pred %p9, %p5, %p6;
    @!%p9 bra NO_RUNNING_UPDATE;
    // rm = (1-m)*rm + m*batch_mean
    // rv = (1-m)*rv + m*batch_var
    // Compute (1 - m)
    sub.f32 %f50, %f48, %f2;       // (1 - momentum)
    // new_rm = rm*(1-m) + m*mean
    mul.f32 %f51, %f42, %f50;
    fma.rn.f32 %f51, %f2, %f33, %f51;
    // new_rv = rv*(1-m) + m*var
    mul.f32 %f52, %f43, %f50;
    fma.rn.f32 %f52, %f2, %f36, %f52;
    mul.wide.u32 %rd88, %r11, 4;
    add.s64 %rd40, %rd5, %rd88;
    add.s64 %rd41, %rd6, %rd88;
    st.global.f32 [%rd40], %f51;
    st.global.f32 [%rd41], %f52;
NO_RUNNING_UPDATE:
    // Store broadcast values to shared memory scalars
    mov.u64 %rd89, sh_used_mean;
    st.shared.f32 [%rd89], %f44;
    mov.u64 %rd90, sh_used_invstd;
    st.shared.f32 [%rd90], %f49;
    mov.u64 %rd91, sh_gamma;
    st.shared.f32 [%rd91], %f40;
    mov.u64 %rd92, sh_beta;
    st.shared.f32 [%rd92], %f41;
    // If (training && track_stats) and c==0, increment num_batches_tracked by 1
    setp.eq.u32 %p10, %r11, 0;     // channel 0
    and.pred %p11, %p9, %p10;
    @!%p11 bra POST_SETUP;
    // increment by 1 (only once)
    // Only thread 0 of block 0 executes here
    ld.global.u64 %rd50, [%rd7];
    add.s64 %rd50, %rd50, 1;
    st.global.u64 [%rd7], %rd50;
POST_SETUP:
    bar.sync 0;
    // Load broadcast scalars from shared memory
    mov.u64 %rd89, sh_used_mean;
    ld.shared.f32 %f60, [%rd89]; // used_mean
    mov.u64 %rd90, sh_used_invstd;
    ld.shared.f32 %f61, [%rd90]; // invstd
    mov.u64 %rd91, sh_gamma;
    ld.shared.f32 %f62, [%rd91]; // gamma
    mov.u64 %rd92, sh_beta;
    ld.shared.f32 %f63, [%rd92]; // beta
    // Output pass
    // Reuse alignment predicate %p16 and HW4 (%r50), t4 start (%r51), stride4 (%r52)
    // Reset t4 start
    shl.b32 %r51, %r10, 2;            // t4 = tid * 4
    @!%p16 bra LOOP_OUT_SCALAR_START;
LOOP_OUT_V:
    setp.ge.u32 %p12, %r51, %r50;
    @%p12 bra AFTER_OUT_V;
    // off0 = base_c + t4
    cvt.u64.u32 %rd60, %r16;        // base_c
    cvt.u64.u32 %rd61, %r51;        // t4
    add.s64 %rd62, %rd60, %rd61;    // off0
    // Inner loop over batches N (vectorized)
    mov.u32 %r31, 0;                // n = 0
     mov.s64 %rd63, %rd62;           // rd_elem = off0
     // Initialize x/y pointers
     shl.b64 %rd64, %rd63, 2;
     add.s64 %rd65, %rd1, %rd64;     // x_ptr_cur
     add.s64 %rd66, %rd2, %rd64;     // y_ptr_cur
LOOP_N_OUT_V:
     setp.ge.u32 %p21, %r31, %r1;
     @%p21 bra AFTER_N_OUT_V;
       ld.global.ca.v4.f32 {%f70, %f71, %f72, %f73}, [%rd65];
     // y = ((x - used_mean) * invstd) * gamma + beta for 4 elems
     sub.f32 %f74, %f70, %f60;
     sub.f32 %f75, %f71, %f60;
     sub.f32 %f76, %f72, %f60;
     sub.f32 %f77, %f73, %f60;
     mul.f32 %f74, %f74, %f61;
     mul.f32 %f75, %f75, %f61;
     mul.f32 %f76, %f76, %f61;
     mul.f32 %f77, %f77, %f61;
     fma.rn.f32 %f74, %f74, %f62, %f63;
     fma.rn.f32 %f75, %f75, %f62, %f63;
     fma.rn.f32 %f76, %f76, %f62, %f63;
     fma.rn.f32 %f77, %f77, %f62, %f63;
     st.global.v4.f32 [%rd66], {%f74, %f75, %f76, %f77};
     // advance to next batch element
     add.u32 %r31, %r31, 1;
     add.s64 %rd65, %rd65, %rd94;    // x_ptr_cur += CHW bytes
     add.s64 %rd66, %rd66, %rd94;    // y_ptr_cur += CHW bytes
     bra LOOP_N_OUT_V;
AFTER_N_OUT_V:
    // Next spatial t4
    add.u32 %r51, %r51, %r52;
    bra LOOP_OUT_V;
AFTER_OUT_V:
    // Tail scalar for t in [HW4, HW)
    mov.u32 %r30, %r10;            // t = tid
    add.u32 %r30, %r30, %r50;      // start at HW4 + tid
LOOP_OUT_TAIL:
    setp.ge.u32 %p22, %r30, %r13;
    @%p22 bra LOOP_OUT_END;
    // off0 = base_c + t
    cvt.u64.u32 %rd60, %r16;        // base_c
    cvt.u64.u32 %rd61, %r30;        // t
    add.s64 %rd62, %rd60, %rd61;    // off0
    // Inner loop over batches N (scalar)
     mov.u32 %r31, 0;                // n = 0
     mov.s64 %rd63, %rd62;           // rd_elem = off0
     // Initialize x/y pointers
     shl.b64 %rd64, %rd63, 2;
     add.s64 %rd65, %rd1, %rd64;     // x_ptr_cur
     add.s64 %rd66, %rd2, %rd64;     // y_ptr_cur
LOOP_N_OUT_TAIL_SC:
     setp.ge.u32 %p23, %r31, %r1;
     @%p23 bra AFTER_N_OUT_TAIL_SC;
       ld.global.ca.f32 %f70, [%rd65];
     // y = ((x - used_mean) * invstd) * gamma + beta
     sub.f32 %f71, %f70, %f60;
     mul.f32 %f72, %f71, %f61;
     fma.rn.f32 %f74, %f72, %f62, %f63;
     st.global.f32 [%rd66], %f74;
     // advance to next batch element
     add.u32 %r31, %r31, 1;
     add.s64 %rd65, %rd65, %rd94;
     add.s64 %rd66, %rd66, %rd94;
     bra LOOP_N_OUT_TAIL_SC;
AFTER_N_OUT_TAIL_SC:
    // Next spatial t
    add.u32 %r30, %r30, %r12;
    bra LOOP_OUT_TAIL;
    // Fallback: full scalar output if misaligned for v4
LOOP_OUT_SCALAR_START:
    mov.u32 %r30, %r10; // t = tid
LOOP_OUT_SCALAR:
    setp.ge.u32 %p24, %r30, %r13;
    @%p24 bra LOOP_OUT_END;
    // off0 = base_c + t
    cvt.u64.u32 %rd60, %r16;        // base_c
    cvt.u64.u32 %rd61, %r30;        // t
    add.s64 %rd62, %rd60, %rd61;    // off0
    // Inner loop over batches N (scalar)
     mov.u32 %r31, 0;                // n = 0
     mov.s64 %rd63, %rd62;           // rd_elem = off0
     // Initialize x/y pointers
     shl.b64 %rd64, %rd63, 2;
     add.s64 %rd65, %rd1, %rd64;     // x_ptr_cur
     add.s64 %rd66, %rd2, %rd64;     // y_ptr_cur
LOOP_N_OUT_SCALAR_INNER:
     setp.ge.u32 %p25, %r31, %r1;
     @%p25 bra AFTER_N_OUT_SCALAR_INNER;
       ld.global.ca.f32 %f70, [%rd65];
     // y = ((x - used_mean) * invstd) * gamma + beta
     sub.f32 %f71, %f70, %f60;
     mul.f32 %f72, %f71, %f61;
     fma.rn.f32 %f74, %f72, %f62, %f63;
     st.global.f32 [%rd66], %f74;
     // advance to next batch element
     add.u32 %r31, %r31, 1;
     add.s64 %rd65, %rd65, %rd94;
     add.s64 %rd66, %rd66, %rd94;
     bra LOOP_N_OUT_SCALAR_INNER;
AFTER_N_OUT_SCALAR_INNER:
    // Next spatial t
    add.u32 %r30, %r30, %r12;
    bra LOOP_OUT_SCALAR;
LOOP_OUT_END:
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("bn2d_onepass")

class ModelNew(nn.Module):
