    // Next spatial t
    add.u32 %r30, %r30, %r12;
    bra LOOP_OUT_TAIL;
    // Fallback: full scalar output if misaligned for v4
LOOP_OUT_SCALAR_START:
    mov.u32 %r30, %r10; // t = tid
LOOP_OUT_SCALAR:
    setp.ge.u32 %p24, %r30, %r13;
    @%p24 bra LOOP_OUT_END;
    // off0 = base_c + t
    cvt.u64.u32 %rd60, %r16;        // base_c
    cvt.u64.u32 %rd61, %r30;        // t
    add.s64 %rd62, %rd60, %rd61;    // off0
    // Inner loop over batches N (scalar)
     mov.u32 %r31, 0;                // n = 0
     mov.s64 %rd63, %rd62;           // rd_elem = off0
     // Initialize x/y pointers
     shl.b64 %rd64, %rd63, 2;
     add.s64 %rd65, %rd1, %rd64;     // x_ptr_cur
     add.s64 %rd66, %rd2, %rd64;     // y_ptr_cur
LOOP_N_OUT_SCALAR_INNER:
     setp.ge.u32 %p25, %r31, %r1;
     @%p25 bra AFTER_N_OUT_SCALAR_INNER;
      ld.global.cg.f32 %f70, [%rd65];
     // y = ((x - used_mean) * invstd) * gamma + beta
     sub.f32 %f71, %f70, %f60;
     mul.f32 %f72, %f71, %f61;
     fma.rn.f32 %f74, %f72, %f62, %f63;
     st.global.f32 [%rd66], %f74;
     // advance to next batch element
     add.u32 %r31, %r31, 1;
     add.s64 %rd65, %rd65, %rd94;
     add.s64 %rd66, %rd66, %rd94;
     bra LOOP_N_OUT_SCALAR_INNER;
AFTER_N_OUT_SCALAR_INNER:
    // Next spatial t
    add.u32 %r30, %r30, %r12;
    bra LOOP_OUT_SCALAR;
LOOP_OUT_END:
DONE:
    ret;
}
CHANNEL_NEXT:
    // advance to next channel and loop
    add.u32 %r11, %r11, %r79;
    bra CHANNEL_LOOP;
KERNEL_DONE:
    ret;
}

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("bn2d_onepass")

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_mean", torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_var", torch.ones(num_features, dtype=torch.float32))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))
        self.eps = 1e-5
        self.momentum = 0.1
        self.track_running_stats = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device for PTX execution."
        assert x.dtype == torch.float32, "Only float32 tensors are supported."
        N, C, H, W = x.shape
        assert C == self.num_features, "Channel dimension must match num_features."

        y = torch.empty((N, C, H, W), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        module.launch(
            "bn2d_onepass",
            grid=(C, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                y,
                self.weight,
                self.bias,
            grid=(max(C, 128), 1, 1),
                self.running_var,
                self.num_batches_tracked,
                i32(N),
                i32(C),
                i32(H),
                i32(W),
                f32(float(self.eps)),
                f32(float(self.momentum)),
                u32(1 if self.training else 0),
                u32(1 if self.track_running_stats else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

