    mov.u32 %r31, 0;                // n = 0
    mov.s64 %rd63, %rd62;           // rd_elem = off0
LOOP_N_OUT_V:
    setp.ge.u32 %p21, %r31, %r1;
    @%p21 bra AFTER_N_OUT_V;
    shl.b64 %rd64, %rd63, 2;
    add.s64 %rd65, %rd1, %rd64;
    ld.global.v4.f32 {%f70, %f71, %f72, %f73}, [%rd65];
