    sub.f32 %f74, %f70, %f60;
    sub.f32 %f75, %f71, %f60;
    sub.f32 %f76, %f72, %f60;
    sub.f32 %f77, %f73, %f60;
    mul.f32 %f74, %f74, %f61;
    mul.f32 %f75, %f75, %f61;
    mul.f32 %f76, %f76, %f61;
    mul.f32 %f77, %f77, %f61;
    fma.rn.f32 %f74, %f74, %f62, %f63;
    fma.rn.f32 %f75, %f75, %f62, %f63;
    fma.rn.f32 %f76, %f76, %f62, %f63;
    fma.rn.f32 %f77, %f77, %f62, %f63;
