    setp.ge.u32 %p23, %r31, %r1;
    @%p23 bra AFTER_N_OUT_TAIL_SC;
    shl.b64 %rd64, %rd63, 2;
    add.s64 %rd65, %rd1, %rd64;
    ld.global.f32 %f70, [%rd65];
